-- CondoConnect: banco da aplicação PHP principal (não da versão alternativa).
-- MySQL 8 / MariaDB 10.6+. UTF-8 completo. Não apaga bancos ou registros.
-- Importe dentro do banco já criado, com o mesmo nome de DB_NAME no .env:
--   mysql -u condo -p db_sisc < db_sisc.sql
-- Pode ser importado de novo sem erro: tabelas e dados de exemplo só são criados se faltarem.

CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 nome VARCHAR(190) NOT NULL,
 cpf VARCHAR(20) NOT NULL,
 email VARCHAR(190) NOT NULL UNIQUE,
 telefone VARCHAR(30) NOT NULL UNIQUE,
 senha VARCHAR(255) NOT NULL,
 condominio_id BIGINT UNSIGNED NULL,
 unidade_id BIGINT UNSIGNED NULL,
 avatar VARCHAR(255) NULL,
 bio TEXT NULL,
 especialidades TEXT NULL,
 servicos_prestados TEXT NULL,
 portfolio_imagens TEXT NULL,
 avaliacao_media DECIMAL(3,2) NOT NULL DEFAULT 0.00,
 documento_certificado VARCHAR(255) NULL,
 certificado_status ENUM('pendente','aprovado','rejeitado') NOT NULL DEFAULT 'aprovado',
 verificado TINYINT(1) NOT NULL DEFAULT 1,
 aprovado_por BIGINT UNSIGNED NULL,
 aprovado_em DATETIME NULL,
 tipo_usuario ENUM('morador','prestador','sindico','admin') NOT NULL DEFAULT 'morador',
 condominio VARCHAR(190) NOT NULL,
 unidade VARCHAR(190) NOT NULL,
 status ENUM('ativo','bloqueado') NOT NULL DEFAULT 'ativo',
 email_verificado TINYINT(1) NOT NULL DEFAULT 1,
 two_factor_enabled TINYINT(1) NOT NULL DEFAULT 0,
 two_factor_code_hash VARCHAR(255) NULL,
 two_factor_expires_at DATETIME NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS condominios (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 nome VARCHAR(190) NOT NULL UNIQUE,
 endereco VARCHAR(255) NOT NULL,
 cidade VARCHAR(190) NOT NULL,
 estado VARCHAR(190) NOT NULL,
 descricao TEXT NULL,
 regras TEXT NULL,
 contato VARCHAR(190) NULL,
 latitude DECIMAL(10,7) NOT NULL,
 longitude DECIMAL(10,7) NOT NULL,
 status ENUM('ativo','inativo') NOT NULL DEFAULT 'ativo',
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS chamados (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 usuario_id BIGINT UNSIGNED NOT NULL,
 condominio_id BIGINT UNSIGNED NULL,
 categoria VARCHAR(100) NOT NULL,
 titulo VARCHAR(190) NOT NULL,
 descricao TEXT NOT NULL,
 local_problema VARCHAR(255) NOT NULL,
 prioridade VARCHAR(20) NOT NULL,
 data_servico DATE NOT NULL,
 protocolo VARCHAR(64) NOT NULL UNIQUE,
 status ENUM('aberto','andamento','concluido','cancelado') NOT NULL DEFAULT 'aberto',
 prestador_id BIGINT UNSIGNED NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CONSTRAINT fk_chamados_condominio FOREIGN KEY (condominio_id) REFERENCES condominios(id),
 INDEX idx_chamados_usuario_data(usuario_id,criado_em),
 INDEX idx_chamados_prestador(prestador_id),
 FOREIGN KEY (usuario_id) REFERENCES users(id) ON DELETE CASCADE,
 CONSTRAINT fk_chamados_prestador FOREIGN KEY (prestador_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS anexos (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 chamado_id BIGINT UNSIGNED NOT NULL,
 arquivo VARCHAR(255) NOT NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (chamado_id) REFERENCES chamados(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mensagens (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 chamado_id BIGINT UNSIGNED NOT NULL,
 remetente_id BIGINT UNSIGNED NOT NULL,
 mensagem TEXT NOT NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (chamado_id) REFERENCES chamados(id) ON DELETE CASCADE,
 FOREIGN KEY (remetente_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notificacoes (
 tipo VARCHAR(60) NOT NULL DEFAULT 'sistema',
 chamado_id BIGINT UNSIGNED NULL,
 chat_id BIGINT UNSIGNED NULL,
 lida_em DATETIME NULL,
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 usuario_id BIGINT UNSIGNED NOT NULL,
 titulo VARCHAR(190) NOT NULL,
 mensagem TEXT NOT NULL,
 lida TINYINT(1) NOT NULL DEFAULT 0,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (usuario_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS avaliacoes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 chamado_id BIGINT UNSIGNED NOT NULL,
 morador_id BIGINT UNSIGNED NOT NULL,
 prestador_id BIGINT UNSIGNED NOT NULL,
 nota TINYINT UNSIGNED NOT NULL,
 comentario TEXT,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_avaliacao_chamado_morador (chamado_id,morador_id),
 CHECK (nota BETWEEN 1 AND 5),
 FOREIGN KEY (chamado_id) REFERENCES chamados(id) ON DELETE CASCADE,
 FOREIGN KEY (morador_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY (prestador_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id BIGINT UNSIGNED NOT NULL,
 token VARCHAR(190) NOT NULL UNIQUE,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contatos (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 nome VARCHAR(190) NOT NULL,
 email VARCHAR(190) NOT NULL,
 assunto VARCHAR(190) NOT NULL,
 mensagem TEXT NOT NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_resets (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id BIGINT UNSIGNED NOT NULL,
 token VARCHAR(255) NOT NULL UNIQUE,
 expires_at DATETIME NOT NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS email_verification_tokens (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id BIGINT UNSIGNED NOT NULL,
 token VARCHAR(255) NOT NULL UNIQUE,
 expires_at DATETIME NOT NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Conversas privadas. O PHP sempre grava user_a_id < user_b_id, evitando pares invertidos.
CREATE TABLE IF NOT EXISTS chats (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_a_id BIGINT UNSIGNED NOT NULL,
 user_b_id BIGINT UNSIGNED NOT NULL,
 pair_min_id BIGINT UNSIGNED GENERATED ALWAYS AS (LEAST(user_a_id,user_b_id)) STORED,
 pair_max_id BIGINT UNSIGNED GENERATED ALWAYS AS (GREATEST(user_a_id,user_b_id)) STORED,
 chamado_id BIGINT UNSIGNED NULL,
 contexto_chamado_id BIGINT UNSIGNED GENERATED ALWAYS AS (COALESCE(chamado_id,0)) STORED,
 ultimo_resumo VARCHAR(255) NULL,
 status ENUM('ativo','encerrado') NOT NULL DEFAULT 'ativo',
 updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_chat_contexto (pair_min_id,pair_max_id,contexto_chamado_id),
 KEY idx_chats_updated (updated_at),
 KEY idx_chats_chamado (chamado_id),
 FOREIGN KEY (user_a_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY (user_b_id) REFERENCES users(id) ON DELETE CASCADE,
 CONSTRAINT fk_chat_chamado FOREIGN KEY (chamado_id) REFERENCES chamados(id) ON DELETE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS chat_participantes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 chat_id BIGINT UNSIGNED NOT NULL,
 usuario_id BIGINT UNSIGNED NOT NULL,
 entrou_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 saiu_em DATETIME NULL,
 ativo TINYINT(1) NOT NULL DEFAULT 1,
 ultima_mensagem_lida_id BIGINT UNSIGNED NULL,
 UNIQUE KEY uk_chat_participante (chat_id,usuario_id),
 KEY idx_participante_usuario (usuario_id,ativo),
 FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE,
 FOREIGN KEY (usuario_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS chat_mensagens (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 chat_id BIGINT UNSIGNED NOT NULL,
 remetente_id BIGINT UNSIGNED NOT NULL,
 mensagem TEXT NOT NULL,
 lida TINYINT(1) NOT NULL DEFAULT 0,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_chat_mensagens_chat (chat_id),
 KEY idx_chat_mensagens_remetente (remetente_id),
 KEY idx_chat_mensagens_data (created_at),
 FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE,
 FOREIGN KEY (remetente_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS auditoria (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 usuario_id BIGINT UNSIGNED NULL,
 acao VARCHAR(100) NOT NULL,
 entidade VARCHAR(100) NULL,
 entidade_id BIGINT UNSIGNED NULL,
 detalhes TEXT NULL,
 ip VARCHAR(45) NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_auditoria_usuario (usuario_id),
 KEY idx_auditoria_data (criado_em),
 FOREIGN KEY (usuario_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS chamado_historico (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 chamado_id BIGINT UNSIGNED NOT NULL,
 usuario_id BIGINT UNSIGNED NULL,
 status_anterior VARCHAR(30) NULL,
 status_novo VARCHAR(30) NOT NULL,
 observacao VARCHAR(500) NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_historico_chamado (chamado_id,criado_em),
 FOREIGN KEY (chamado_id) REFERENCES chamados(id) ON DELETE CASCADE,
 FOREIGN KEY (usuario_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;


CREATE TABLE IF NOT EXISTS blocos (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 condominio_id BIGINT UNSIGNED NOT NULL,
 nome VARCHAR(80) NOT NULL,
 UNIQUE KEY uk_bloco (condominio_id,nome),
 UNIQUE KEY uk_bloco_cond (id,condominio_id),
 FOREIGN KEY (condominio_id) REFERENCES condominios(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS unidades (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 bloco_id BIGINT UNSIGNED NOT NULL,
 condominio_id BIGINT UNSIGNED NOT NULL,
 numero VARCHAR(30) NOT NULL,
 UNIQUE KEY uk_unidade (bloco_id,numero),
 UNIQUE KEY uk_unidade_cond (id,condominio_id),
 FOREIGN KEY (bloco_id,condominio_id) REFERENCES blocos(id,condominio_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS condominio_sindicos (
 condominio_id BIGINT UNSIGNED PRIMARY KEY,
 usuario_id BIGINT UNSIGNED NOT NULL,
 atribuido_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (condominio_id) REFERENCES condominios(id),
 FOREIGN KEY (usuario_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS areas_comuns (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 condominio_id BIGINT UNSIGNED NOT NULL,
 nome VARCHAR(120) NOT NULL,
 descricao TEXT,
 capacidade INT UNSIGNED NOT NULL DEFAULT 10,
 regras TEXT,
 ativo TINYINT(1) NOT NULL DEFAULT 1,
 UNIQUE KEY uk_area (condominio_id,nome),
 UNIQUE KEY uk_area_cond (id,condominio_id),
 FOREIGN KEY (condominio_id) REFERENCES condominios(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reservas (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 area_id BIGINT UNSIGNED NOT NULL,
 condominio_id BIGINT UNSIGNED NOT NULL,
 usuario_id BIGINT UNSIGNED NOT NULL,
 inicio DATETIME NOT NULL,
 fim DATETIME NOT NULL,
 status ENUM('confirmada','cancelada') NOT NULL DEFAULT 'confirmada',
 observacao VARCHAR(500),
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_reserva_usuario_horario (area_id,usuario_id,inicio),
 KEY idx_reserva_agenda (area_id,status,inicio,fim),
 FOREIGN KEY (area_id,condominio_id) REFERENCES areas_comuns(id,condominio_id),
 FOREIGN KEY (usuario_id) REFERENCES users(id),
 CHECK (fim > inicio)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comunicados (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 condominio_id BIGINT UNSIGNED NOT NULL,
 autor_id BIGINT UNSIGNED NOT NULL,
 titulo VARCHAR(190) NOT NULL,
 conteudo TEXT NOT NULL,
 status ENUM('rascunho','publicado','arquivado','excluido') NOT NULL DEFAULT 'publicado',
 publicado_em DATETIME NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 atualizado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 KEY idx_comunicado_cond (condominio_id,status,publicado_em),
 FOREIGN KEY (condominio_id) REFERENCES condominios(id),
 FOREIGN KEY (autor_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comunicado_leituras (
 comunicado_id BIGINT UNSIGNED NOT NULL,
 usuario_id BIGINT UNSIGNED NOT NULL,
 lido_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY (comunicado_id,usuario_id),
 FOREIGN KEY (comunicado_id) REFERENCES comunicados(id) ON DELETE CASCADE,
 FOREIGN KEY (usuario_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comunicado_historico (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 comunicado_id BIGINT UNSIGNED NOT NULL,
 usuario_id BIGINT UNSIGNED NOT NULL,
 titulo VARCHAR(190) NOT NULL,
 conteudo TEXT NOT NULL,
 status VARCHAR(20) NOT NULL,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (comunicado_id) REFERENCES comunicados(id),
 FOREIGN KEY (usuario_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chamado_propostas (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 chamado_id BIGINT UNSIGNED NOT NULL,
 prestador_id BIGINT UNSIGNED NOT NULL,
 resposta TEXT NOT NULL,
 taxa_visita DECIMAL(10,2) NULL,
 visita_em DATETIME NULL,
 orcamento_valor DECIMAL(10,2) NULL,
 orcamento_descricao TEXT NULL,
 orcamento_status ENUM('pendente','aceito','recusado') NOT NULL DEFAULT 'pendente',
 atualizado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_proposta (chamado_id,prestador_id),
 FOREIGN KEY (chamado_id) REFERENCES chamados(id),
 FOREIGN KEY (prestador_id) REFERENCES users(id),
 CHECK (taxa_visita IS NULL OR taxa_visita >= 0),
 CHECK (orcamento_valor IS NULL OR orcamento_valor > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Chaves estrangeiras entre tabelas criadas acima; cada uma só é adicionada se ainda não existir.
SET @sisc_sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE users ADD CONSTRAINT fk_users_condominio FOREIGN KEY (condominio_id) REFERENCES condominios(id)', 'DO 0') FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND CONSTRAINT_NAME = 'fk_users_condominio' AND CONSTRAINT_TYPE = 'FOREIGN KEY');
PREPARE sisc_stmt FROM @sisc_sql;
EXECUTE sisc_stmt;
DEALLOCATE PREPARE sisc_stmt;
SET @sisc_sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE users ADD CONSTRAINT fk_users_unidade FOREIGN KEY (unidade_id,condominio_id) REFERENCES unidades(id,condominio_id)', 'DO 0') FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'users' AND CONSTRAINT_NAME = 'fk_users_unidade' AND CONSTRAINT_TYPE = 'FOREIGN KEY');
PREPARE sisc_stmt FROM @sisc_sql;
EXECUTE sisc_stmt;
DEALLOCATE PREPARE sisc_stmt;
SET @sisc_sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE notificacoes ADD CONSTRAINT fk_notice_ticket FOREIGN KEY (chamado_id) REFERENCES chamados(id) ON DELETE SET NULL', 'DO 0') FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'notificacoes' AND CONSTRAINT_NAME = 'fk_notice_ticket' AND CONSTRAINT_TYPE = 'FOREIGN KEY');
PREPARE sisc_stmt FROM @sisc_sql;
EXECUTE sisc_stmt;
DEALLOCATE PREPARE sisc_stmt;
SET @sisc_sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE notificacoes ADD CONSTRAINT fk_notice_chat FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE SET NULL', 'DO 0') FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = DATABASE() AND TABLE_NAME = 'notificacoes' AND CONSTRAINT_NAME = 'fk_notice_chat' AND CONSTRAINT_TYPE = 'FOREIGN KEY');
PREPARE sisc_stmt FROM @sisc_sql;
EXECUTE sisc_stmt;
DEALLOCATE PREPARE sisc_stmt;

